window.translatePage=function(l){const d=window.I18N[l];if(!d)return;const keys=Object.keys(d).sort((a,b)=>b.length-a.length);
const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);const ns=[];while(w.nextNode())ns.push(w.currentNode);
for(const n of ns){let t=n.nodeValue;const tr=t.trim();if(!tr)continue;if(d[tr]){n.nodeValue=t.replace(tr,d[tr]);continue;}for(const k of keys){if(k.length>3&&t.includes(k))t=t.split(k).join(d[k]);}n.nodeValue=t;}};
